mapper.select:
select a.id, a.anchor_url_sec_uid as sec_uid, a.trade_id, a.account_type, a.last_record_time,a.is_barrage_monitoring as enable_barrage_monitoring, is_data_viewing as enable_data_viewing,
a.user_id, a.is_auto_analysis as enable_auto_analysis

    , b.anchor_name , b.anchor_number, b.platform, b.anchor_avatar

from tb_anchor_url_user as a

           join tb_anchor_url as b on a.anchor_url_sec_uid = b.sec_uid

where a.is_deleted = 0 and a.tenant_id = #{tenantId}

    and a.user_id = #{userId}


    and a.is_auto_upload_cloud = 1


    and (a.user_id = #{userId} or a.is_auto_upload_cloud = 1)


    and b.anchor_name like concat('%',#{anchorName},'%')


    and b.anchor_number = #{anchorNumber}


    and b.platform in

        #{item}



    and a.create_date >= #{addStartDate}


    and a.create_date <= #{addEndDate}


    and a.last_record_time >= #{lastRecordStartDate}


    and a.last_record_time <= #{lastRecordEndDate}


    and a.trade_id in

        #{item}



    and a.account_type = #{accountType}


    and a.id < #{cursor}

order by a.id desc limit #{pageSize}
